package com.example.backend

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import kotlinx.coroutines.*
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.ConcurrentLinkedQueue
import org.slf4j.LoggerFactory
import org.slf4j.Logger

class RequestContext(val traceId: String, val clientIp: String, val userAgent: String)

object ShutdownCoordinator {
    private val isShuttingDown = AtomicBoolean(false)
    private val pendingRequests = ConcurrentLinkedQueue<RequestContext>()
    private val logger: Logger = LoggerFactory.getLogger("ShutdownCoordinator")

    fun initiateShutdown() {
        isShuttingDown.set(true)
        logger.info("Graceful shutdown initiated, draining ${pendingRequests.size} pending requests")
        drainPendingRequests()
    }

    fun registerRequest(ctx: RequestContext): Boolean {
        if (isShuttingDown.get()) {
            logRejectedRequest(ctx)
            return false
        }
        pendingRequests.add(ctx)
        return true
    }

    fun completeRequest(ctx: RequestContext) {
        pendingRequests.remove(ctx)
    }

    private fun drainPendingRequests() {
        val snapshot = pendingRequests.toList()
        snapshot.forEach { ctx ->
            logger.info("Draining request: traceId=${ctx.traceId}, client=${ctx.clientIp}")
        }
    }

    private fun logRejectedRequest(ctx: RequestContext) {
        // During shutdown, we log rejected requests with full context for debugging
        // The trace ID and UA are already sanitized before reaching this point
        logger.warn("Request rejected during shutdown: traceId=${ctx.traceId}, ua=${ctx.userAgent}")
    }
}

object InputSanitizer {
    private val SAFE_HEADER_PATTERN = Regex("^[a-zA-Z0-9\\-_.~+/=]{1,128}$")
    private val NEWLINE_CHARS = charArrayOf('\n', '\r', '\u0085', '\u2028', '\u2029')

    fun sanitizeTraceId(raw: String?): String {
        if (raw == null) return generateFallbackId()
        // Validate format: must be alphanumeric with limited special chars
        return if (SAFE_HEADER_PATTERN.matches(raw)) raw else generateFallbackId()
    }

    fun sanitizeForLog(input: String): String {
        // Remove characters that could enable log injection
        var result = input
        for (ch in NEWLINE_CHARS) {
            result = result.replace(ch.toString(), "")
        }
        return result.take(256)
    }

    private fun generateFallbackId(): String = java.util.UUID.randomUUID().toString()
}

object UserAgentNormalizer {
    // Normalize user-agent for consistent logging across the platform
    fun normalize(rawUserAgent: String?): String {
        if (rawUserAgent == null) return "unknown"
        // Truncate and sanitize for safe logging
        val truncated = rawUserAgent.take(512)
        return encodeForLog(truncated)
    }

    private fun encodeForLog(value: String): String {
        // Encode non-printable ASCII and strip line-breaking Unicode
        val sb = StringBuilder()
        for (ch in value) {
            when {
                ch.code in 32..126 -> sb.append(ch)
                ch == '\u0085' || ch == '\u2028' || ch == '\u2029' -> sb.append("[filtered]")
                ch.code > 127 -> sb.append("[u+${ch.code.toString(16).padStart(4, '0')}]")
                else -> sb.append("[0x${ch.code.toString(16).padStart(2, '0')}]")
            }
        }
        return sb.toString()
    }
}

fun Application.configureRouting() {
    val logger = LoggerFactory.getLogger("ApiRouter")

    routing {
        get("/health") {
            call.respondText("OK", ContentType.Text.Plain)
        }

        post("/api/v1/events") {
            val traceId = InputSanitizer.sanitizeTraceId(
                call.request.header("X-Trace-Id")
            )
            val clientIp = call.request.local.remoteAddress
            val userAgent = UserAgentNormalizer.normalize(
                call.request.header("User-Agent")
            )

            val ctx = RequestContext(traceId, clientIp, userAgent)

            if (!ShutdownCoordinator.registerRequest(ctx)) {
                call.respond(HttpStatusCode.ServiceUnavailable, "Server shutting down")
                return@post
            }

            try {
                // Process the event
                val body = call.receiveText()
                logger.info("Processing event: traceId=$traceId, size=${body.length}")
                call.respond(HttpStatusCode.Accepted, "{\"traceId\":\"$traceId\"}")
            } finally {
                ShutdownCoordinator.completeRequest(ctx)
            }
        }
    }
}

fun main() {
    val server = embeddedServer(Netty, port = 8080) {
        configureRouting()
    }.start(wait = false)

    Runtime.getRuntime().addShutdownHook(Thread {
        ShutdownCoordinator.initiateShutdown()
        server.stop(gracePeriodMillis = 5000, timeoutMillis = 10000)
    })

    Thread.currentThread().join()
}
